begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select plan(16);
insert into auth.users(id,email) values ('55555555-5555-4555-8555-555555555555','reports-a@example.invalid'),('66666666-6666-4666-8666-666666666666','reports-b@example.invalid');
select ok((select relrowsecurity from pg_class where oid='public.content_reports'::regclass),'Content reports use RLS');
set local role service_role;
select lives_ok($$select append_content_reports('55555555-5555-4555-8555-555555555555','[{"report":{"id":"00000000-0000-4000-8000-000000000001","message":"Beispiel","locale":"de","category":"audio"},"content_id":"practice:mini","content_version":1,"item":{},"evaluation":null}]')$$,'Trusted backend submits a report');
select lives_ok($$select append_content_reports('55555555-5555-4555-8555-555555555555','[{"report":{"id":"00000000-0000-4000-8000-000000000001","message":"Beispiel","locale":"de","category":"audio"},"content_id":"practice:mini","content_version":1,"item":{},"evaluation":null}]')$$,'Retry is idempotent');
select is((select count(*)::integer from content_reports),1,'One report is stored');
select is((select status from content_reports limit 1),'new','Clients do not choose review status');
select throws_ok($$select append_content_reports('55555555-5555-4555-8555-555555555555','[{"report":{"id":"00000000-0000-4000-8000-000000000001","message":"changed","locale":"de","category":"audio"},"content_id":"practice:mini","content_version":1}]')$$,'P0001',null,'Changed retry conflicts');
select throws_ok($$select append_content_reports('55555555-5555-4555-8555-555555555555',null)$$,'P0001',null,'Null batch is rejected');
set local role anon;
select throws_ok('select * from content_reports','42501',null,'Guests cannot read reports');
select throws_ok($$select append_content_reports('55555555-5555-4555-8555-555555555555','[]')$$,'42501',null,'Guests cannot call append RPC');
set local role authenticated;
set local request.jwt.claims='{"sub":"55555555-5555-4555-8555-555555555555","role":"authenticated"}';
select is((select count(*)::integer from content_reports),1,'Owner can read own reports');
select throws_ok($$insert into content_reports(user_id,client_id,content_id,content_version,message,locale,category,request,context) values ('55555555-5555-4555-8555-555555555555','00000000-0000-4000-8000-000000000002','forged',1,'','de','audio','{}','{}')$$,'42501',null,'Direct writes cannot bypass source verification');
select throws_ok($$update content_reports set status='resolved'$$,'42501',null,'Clients cannot resolve reports');
select throws_ok('delete from content_reports','42501',null,'Clients cannot delete reports');
select throws_ok($$select append_content_reports('55555555-5555-4555-8555-555555555555','[]')$$,'42501',null,'Clients cannot call trusted RPC');
set local request.jwt.claims='{"sub":"66666666-6666-4666-8666-666666666666","role":"authenticated"}';
select is((select count(*)::integer from content_reports),0,'Other account sees no reports');
reset role;
delete from auth.users where id='55555555-5555-4555-8555-555555555555';
select is((select count(*)::integer from content_reports),0,'Account deletion removes reports');
select * from finish();
rollback;
